"""Reproduce with: python3 .runtime/predecessor-proof.py STEP.
Private generated env/dumps/state remain ignored. This source contains no credentials.
"""
import hashlib,json,os,secrets,shutil,socket,subprocess,sys,tarfile,time
from datetime import UTC,datetime
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
POINTER=ROOT/'.runtime/predecessor-current.json'
STEP=sys.argv[1]
IMAGE='postgres:17.11@sha256:ff87138949ad9a46f32ff23bd6852b52ce024a13dffe9b4087be98292cdd3b4f'
if STEP=='prepare':
    stamp=datetime.now(UTC).strftime('%Y%m%d%H%M%S')
    base=ROOT/'.runtime'/('predecessor-'+stamp)
    base.mkdir(mode=0o700)
    data={'base':str(base),'stamp':stamp,'created':[],'roles':{},'steps':{},'predecessor_commit':'15079aa7149b0a699891ddb10d8ccf5d06633608','candidate_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()}
    POINTER.write_text(json.dumps(data))
else:
    data=json.loads(POINTER.read_text());base=Path(data['base'])
INSTALL=base/'installation'
EVIDENCE=ROOT/'docs/F23-docker-completo-e-ia-integrada/evidence'/('predecessor-proof-'+data['stamp']+'.json')

def save():
    POINTER.write_text(json.dumps(data,indent=2))
    public={k:v for k,v in data.items() if k not in {'roles'}}
    public['resources']={r:{'environment':d['environment'],'pg':d['pg'],'project':d['project']} for r,d in data['roles'].items()}
    EVIDENCE.write_text(json.dumps(public,indent=2)+'\n')

def run(args,label,stdin=None,env=None,expected=0):
    result=subprocess.run(args,input=stdin,text=True,capture_output=True,env=env)
    (base/(label+'.log')).write_text(result.stdout+result.stderr)
    data['steps'][label]={'exit_code':result.returncode,'command':args,'log_private':str(base/(label+'.log'))}
    save()
    if result.returncode!=expected:
        raise RuntimeError(label+' exit '+str(result.returncode)+'; private log '+str(base/(label+'.log')))
    return result.stdout

def free_port():
    for _ in range(100):
        selected=20000+secrets.randbelow(10000)
        with socket.socket() as s:
            try:s.bind(('127.0.0.1',selected))
            except OSError:continue
            return selected
    raise RuntimeError('No free controlled port in 20000-29999')

def execute(role,action,label=None):
    shutil.copyfile(ROOT/'.runtime/predecessor-action.py',base/'action.py')
    label=label or role+'-'+action
    run(['docker','exec',data['executor'],'/app/apps/backend/.venv/bin/python',str(base/'action.py'),str(INSTALL),data['roles'][role]['env'],action,str(base/(label+'.json'))],label)
    return json.loads((base/(label+'.json')).read_text())

def helper(role,action):
    return run(['bash',str(INSTALL/'scripts/docker-adoption.sh'),action,data['roles'][role]['project'],str(base/'cold-copy')],role+'-'+action)

def files(role):
    result={}
    for surface,folder in data['roles'][role]['paths'].items():
        root=Path(folder)
        result[surface]={str(p.relative_to(root)).replace(data['roles'][role]['environment']+'/', '<ENV>/'):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size,'mode':oct(p.stat().st_mode&0o777)} for p in root.rglob('*') if p.is_file() and p!=root/'.garimpei-owner'}
    return result

def verify_restart():
    source=data['source_inventory'];target=data['target_restarted_inventory']
    assert source['receipts']==target['receipts']
    assert source['original_technical_queue']==target['original_technical_queue']
    for table in ('runtime_robotcontrol','runtime_robotcontrolcommand','runtime_robotoperation','runtime_listingobservation','runtime_conditionassessment','runtime_assessmenthead','runtime_inferencerequest','runtime_inferencepart','persistence_monitoringconfiguration','persistence_monitoringinterest','runtime_manualcondition','runtime_valuationevaluation'):
        assert source['tables'][table]==target['tables'][table],table
    def listing_rows(role):
        entry=data['roles'][role]
        raw=subprocess.check_output(['docker','exec',entry['pg'],'psql','-U','garimpei','-d','garimpei_'+entry['environment'],'-Atqc','SELECT row_to_json(l) FROM runtime_listing l ORDER BY id'],text=True)
        return {r['id']:r for r in map(json.loads,raw.splitlines())}
    before=listing_rows('source');after=listing_rows('target')
    assert before.keys()==after.keys()
    differences=[]
    for identity,row in before.items():
        changed={key:{'before':value,'after':after[identity][key]} for key,value in row.items() if value!=after[identity][key]}
        assert set(changed)<= {'media_refresh_after'},(identity,changed)
        if changed:differences.append({'listing_id':identity,'fields':changed})
    data['restart_verified']={'strict_original_rows_and_queue_preserved':True,'only_listing_field_allowed_to_change':'media_refresh_after','technical_schedule_diffs':differences,'new_runtime_tables_expected':True}

def verify_files(role):
    current=files(role);original=data['source_files']
    allowed={'media/.garimpei-media-owner','backups/.garimpei-backup-owner'}
    for surface,entries in original.items():
        expected={k:v for k,v in entries.items() if surface!='private' or k not in allowed}
        actual={k:v for k,v in current[surface].items() if surface!='private' or k not in allowed}
        assert expected==actual,(role,surface)
    private=Path(data['roles'][role]['paths']['private'])
    rebound={name:(private/name).read_text()==data['roles'][role]['environment'] for name in allowed}
    assert all(rebound.values()),rebound
    data.setdefault('owner_metadata_rebinding',{})[role]=rebound
    return current

try:
    if STEP=='prepare':
        INSTALL.mkdir()
        archive=base/'old.tar'
        with archive.open('wb') as output:subprocess.run(['git','archive','15079'],cwd=ROOT,stdout=output,check=True)
        with tarfile.open(archive) as tar:tar.extractall(INSTALL,filter='data')
        shutil.copyfile(ROOT/'scripts/docker-adoption.sh',INSTALL/'scripts/docker-adoption.sh')
        data['helper_sha256']=hashlib.sha256((INSTALL/'scripts/docker-adoption.sh').read_bytes()).hexdigest()
        executor='garimpei-predecessor-executor-'+data['stamp']
        data['executor']=executor
        executor_identity='eval_pred_executor_'+data['stamp'][-10:]
        run(['docker','run','-d','--name',executor,'--label','com.docker.compose.project=garimpei-'+executor_identity,'--label','com.docker.compose.service=quality','--label','com.garimpei.checkout='+str(INSTALL),'--label','com.garimpei.environment='+executor_identity,'--user','1000:1000','--group-add','1001','--network','host','--mount','type=bind,source='+str(base)+',destination='+str(base),'--mount','type=bind,source=/var/run/docker.sock,destination=/var/run/docker.sock','--entrypoint','sleep','garimpei-quality:f23-eval_f23_runtime','infinity'],'executor-create')
        data['created'].append(executor);save()
        for role in ('source','f17','target','rollback'):
            identity='eval_pred_'+role+'_'+data['stamp'][-10:]
            project='garimpei-'+identity; pg=project+'-postgres'
            paths={k:base/role/k for k in ('private','state','waha','ollama')}
            for path in paths.values():path.mkdir(parents=True,mode=0o700)
            (paths['state']/identity/'inference').mkdir(parents=True)
            (paths['private']/'.garimpei-owner').write_text(str(INSTALL)+'\n'+identity+'\n')
            private=base/(role+'.env');port=free_port()
            values={'GARIMPEI_ENV':'eval','GARIMPEI_INSTANCE':identity[5:],'GARIMPEI_RUNTIME':'host','DJANGO_SECRET_KEY':secrets.token_urlsafe(40),'POSTGRES_PASSWORD':secrets.token_urlsafe(32),'WAHA_API_KEY':secrets.token_urlsafe(32),'GARIMPEI_PG_PORT':str(port),'GARIMPEI_WEB_PORT':str(free_port()),'GARIMPEI_WAHA_PORT':str(free_port()),'GARIMPEI_AI_PORT':str(free_port()),'GARIMPEI_AI_SERVICE_ENABLED':'false','GARIMPEI_ALERTS_ENABLED':'false','GARIMPEI_ASSESSMENT_ENABLED':'false','GARIMPEI_LISTING_FIXTURE_URL':'http://127.0.0.1:9','GARIMPEI_LISTING_FIXTURE_CLOCK':str(base/'clock'),'GARIMPEI_BACKUP_DIR':str(paths['private']/'backups'),'GARIMPEI_MEDIA_ROOT':str(paths['private']/'media'),'GARIMPEI_MEDIA_BUDGET_BYTES':'67108864','GARIMPEI_MEDIA_MAX_FILE_BYTES':'1048576','GARIMPEI_INTEGRATION_STATE_DIR':str(paths['private']/'integrations')}
            private.write_text(''.join(k+'='+v+'\n' for k,v in values.items()));private.chmod(0o600)
            directory=INSTALL/'.runtime'/identity;directory.mkdir(parents=True)
            manifest={'environment_id':identity,'checkout':str(INSTALL),'run_id':'controlled-predecessor','ports':{'pg':port,'web':int(values['GARIMPEI_WEB_PORT']),'waha':int(values['GARIMPEI_WAHA_PORT']),'ai':int(values['GARIMPEI_AI_PORT'])},'processes':[],'containers':[],'disposable':True,'session_kind':'synthetic','status':'quiescent'}
            (directory/'manifest.json').write_text(json.dumps(manifest));(directory/'docker-disposable').write_text('owned controlled predecessor assay\n')
            labels=['--label','com.docker.compose.project='+project,'--label','com.garimpei.checkout='+str(INSTALL),'--label','com.garimpei.environment='+identity]
            pgdata=base/role/'pg-data';pgdata.mkdir(mode=0o700)
            data['created'].append(pg);save()
            run(['docker','run','-d','--name',pg,'--mount','type=bind,source='+str(pgdata)+',destination=/var/lib/postgresql/data','-p','127.0.0.1:'+str(port)+':5432','-e','POSTGRES_PASSWORD','-e','POSTGRES_USER=garimpei','-e','POSTGRES_DB=garimpei_'+identity,*labels,'--label','com.docker.compose.service=postgres',IMAGE],role+'-pg-create',env=dict(os.environ,POSTGRES_PASSWORD=values['POSTGRES_PASSWORD']))
            data['roles'][role]={'environment':identity,'project':project,'pg':pg,'env':str(private),'paths':{k:str(v) for k,v in paths.items()}}
            save()
            for _ in range(100):
                if subprocess.run(['docker','exec',pg,'pg_isready','-U','garimpei','-d','garimpei_'+identity],capture_output=True).returncode==0:break
                time.sleep(.2)
            else:raise RuntimeError('Owned PostgreSQL readiness failed')
            for service,dest,key in (('worker','/private','private'),('waha','/app/.sessions','waha'),('ollama','/root/.ollama','ollama')):
                name=project+'-'+service
                mounts=['--mount','type=bind,source='+str(paths[key])+',destination='+dest]
                if service=='worker':mounts+=['--mount','type=bind,source='+str(paths['state'])+',destination=/state']
                run(['docker','create','--name',name,'--network','none','--tmpfs','/var/lib/postgresql/data',*labels,'--label','com.docker.compose.service='+service,*mounts,'--entrypoint','/bin/true',IMAGE],role+'-'+service+'-holder')
                data['created'].append(name);save()
        (base/'clock').write_text(datetime.now(UTC).replace(microsecond=0).isoformat())
        data['scope']='Real predecessor Django0027/F17 and current migration; controlled filesystem holders, no real sessions/model/GPU.'
    elif STEP=='seed':
        execute('source','migrate');execute('source','seed')
        source=data['roles']['source'];paths={k:Path(v) for k,v in source['paths'].items()}
        for key,name,payload in [('private','integrations/profile/synthetic-session.bin',b'CONTROLLED predecessor browser profile, no account'),('waha','synthetic-session.bin',b'CONTROLLED predecessor WAHA session, no account'),('ollama','models/blobs/synthetic-weights.bin',b'CONTROLLED sentinel weights; not a model'),('state',source['environment']+'/inference/tokenizer.json',b'{"controlled_predecessor_tokenizer":true}')]:
            p=paths[key]/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(payload)
        data['source_media_read']=execute('source','media-read')
        data['f17_backup']=execute('source','backup')
        data['source_inventory']=execute('source','inventory')
    elif STEP=='resume-seed-inventory':
        assert 'f17_backup' in data
        data['source_inventory']=execute('source','inventory')
        data['steps']['seed']={'status':'PASS','note':'Seed/backup succeeded originally; retried read-only inventory after decoding PostgreSQL JSON text correctly.'}
    elif STEP=='f17':
        if 'f17_restore' not in data:
            execute('f17','migrate');data['f17_restore']=execute('f17','restore');data['f17_inventory']=execute('f17','inventory')
        source=data['source_inventory'];target=data['f17_inventory']
        assert source['listing_ids']==target['listing_ids'] and source['receipts']==target['receipts']
        for table in ('runtime_listing','runtime_listingobservation','persistence_monitoringconfiguration','persistence_monitoringinterest','runtime_conditionassessment','runtime_assessmenthead','runtime_inferencerequest','runtime_inferencepart','runtime_manualcondition','runtime_valuationevaluation'):
            assert source['tables'][table]==target['tables'][table],table
        data['f17_restore']['core_ids_counts_receipts_verified']=True
        data['f17_restore']['core_row_hashes_verified']=True
        data['f17_media_read']=execute('f17','media-read')
    elif STEP=='inventory-before':
        data['source_inventory']=execute('source','inventory')
        data['f17_inventory']=execute('f17','inventory')
    elif STEP=='snapshot':
        private=Path(data['roles']['source']['paths']['private'])
        (private/'backups').mkdir(exist_ok=True)
        shutil.copyfile(data['f17_backup']['archive'],private/'backups/verified-predecessor-f17.archive')
        (private/'config').mkdir(exist_ok=True)
        shutil.copyfile(data['roles']['source']['env'],private/'config/synthetic-runtime.env')
        data['source_files']=files('source')
        helper('source','snapshot')
        data['snapshot_ready']=(base/'cold-copy/READY').exists()
    elif STEP=='adopt':
        helper('target','restore-check');data['target_before_migrate']=execute('target','inventory','target-before-inventory')
        assert data['source_inventory']['tables']==data['target_before_migrate']['tables']
        data['target_files']=verify_files('target')
        for name in ('src','tests'):
            shutil.rmtree(INSTALL/'apps/backend'/name)
            shutil.copytree(ROOT/'apps/backend'/name,INSTALL/'apps/backend'/name,ignore=shutil.ignore_patterns('__pycache__','.pytest_cache'))
        data['candidate_effective_files']={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [ROOT/'apps/backend/src/garimpei/infra/persistence/migrations/0030_inference_legacy_targets.py',ROOT/'apps/backend/src/garimpei/infra/persistence/migrations/0031_assisted_gold_authorization.py',ROOT/'scripts/docker-adoption.sh']}
        data['target_migrate']=execute('target','migrate');data['target_after_migrate']=execute('target','inventory','target-after-inventory')
        for table,value in data['source_inventory']['tables'].items():
            if table!='django_migrations':assert value==data['target_after_migrate']['tables'][table],table
        execute('target','barrier');data['target_probe']=execute('target','probe')
        data['target_media_read']=execute('target','media-read')
        data['target_new_backup']=execute('target','new-backup')
    elif STEP=='restart':
        target=data['roles']['target']
        run(['docker','restart',target['pg']],'target-postgres-restart')
        for _ in range(100):
            if subprocess.run(['docker','exec',target['pg'],'pg_isready','-U','garimpei','-d','garimpei_'+target['environment']],capture_output=True).returncode==0:break
            time.sleep(.2)
        else:raise RuntimeError('Restarted owned PostgreSQL did not become ready')
        data['postgres_restarted_with_bind_data']=True
        data['real_worker_restarts']=execute('target','worker')
        data['target_restart_probe']=execute('target','probe','target-restart-probe')
        data['target_restarted_inventory']=execute('target','inventory','target-restarted-inventory')
        verify_restart()
    elif STEP=='verify-restart':
        verify_restart()
        data['steps']['restart_initial_inventory_assertion']={'status':'FAIL','reason':'The original full-row equality included media_refresh_after; exact SQL differences are retained in restart_verified. No observation/receipt/configuration loss.'}
        data['steps']['restart']={'status':'PASS','at':datetime.now(UTC).isoformat(),'verification':'strict original data/queue plus explicit scheduling-field allowlist'}
    elif STEP=='rollback':
        helper('rollback','restore-check')
        # Restore the previous code without reversing the adopted database in place.
        previous=base/'previous-code';previous.mkdir()
        with tarfile.open(base/'old.tar') as tar:tar.extractall(previous,filter='data')
        for name in ('src','tests'):
            shutil.rmtree(INSTALL/'apps/backend'/name);shutil.copytree(previous/'apps/backend'/name,INSTALL/'apps/backend'/name)
        data['rollback_inventory']=execute('rollback','inventory')
        assert data['rollback_inventory']['tables']==data['source_inventory']['tables']
        data['rollback_files']=verify_files('rollback')
        execute('rollback','barrier');data['rollback_probe']=execute('rollback','probe')
        data['rollback_media_read']=execute('rollback','media-read')
        data['rollback_new_backup']=execute('rollback','new-backup')
    elif STEP=='cleanup':
        for name in reversed(data['created']):run(['docker','rm','-fv',name],'cleanup-'+name)
        data['cleanup']='Only exact assay-created containers removed; generated private files retained ignored.'
    else:raise ValueError(STEP)
    data['steps'][STEP]={'status':'PASS','at':datetime.now(UTC).isoformat()}
except Exception as error:
    data['steps'][STEP]={'status':'FAIL','error':str(error),'at':datetime.now(UTC).isoformat()}
    raise
finally:
    save();print(EVIDENCE)
